frappe.ui.form.on("Items", {
    quantity(frm, cdt, cdn) {
        calculate_total(cdt, cdn);
    },

    price(frm, cdt, cdn) {
        calculate_total(cdt, cdn);
    }
});

function calculate_total(cdt, cdn) {
    let row = locals[cdt][cdn];

    frappe.model.set_value(
        cdt,
        cdn,
        "total",
        (row.quantity || 0) * (row.price || 0)
    );
}

frappe.ui.form.on("ProdItems", {
    quantity(frm, cdt, cdn) {
        calculate_total(cdt, cdn);
    },

    price(frm, cdt, cdn) {
        calculate_total(cdt, cdn);
    }
});

function calculate_total(cdt, cdn) {
    let row = locals[cdt][cdn];

